.darma-loader-tw-bell-ring { position: relative; display: inline-block; width: var(--loader-size, 60px); height: var(--loader-size, 60px); }
.darma-loader-tw-bell-ring .darma-loader-tw-bell-ring__bell { position: absolute; left: 16%; top: 12%; width: 68%; height: 60%; border-radius: 50% 50% 12% 12%; background: var(--loader-color, #f59e0b); transform-origin: 50% 0; animation: darma-loader-tw-bell-ring-twSwing calc(var(--loader-speed, 1s) * 1.2) ease-in-out infinite; }
.darma-loader-tw-bell-ring .darma-loader-tw-bell-ring__bell::after { content: ''; position: absolute; left: -14%; bottom: -8%; width: 128%; height: 14%; border-radius: 9999px; background: var(--loader-color, #f59e0b); }
.darma-loader-tw-bell-ring .darma-loader-tw-bell-ring__clapper { position: absolute; left: 42%; bottom: 16%; width: 16%; height: 16%; border-radius: 9999px; background: var(--loader-secondary-color, #ef4444); animation: darma-loader-tw-bell-ring-twClap calc(var(--loader-speed, 1s) * 1.2) ease-in-out infinite; }
@keyframes darma-loader-tw-bell-ring-twSwing { 0%, 100% { transform: rotate(-13deg); } 50% { transform: rotate(13deg); } }
@keyframes darma-loader-tw-bell-ring-twClap { 0%, 100% { transform: translateX(-32%); } 50% { transform: translateX(32%); } }

